{
  "name": "计算节点服务器",
  "name_en": "Compute Node Server",
  "manufacturer": "",
  "description": "用于实验室分布式计算或数据处理集群的节点服务器软件，通常运行在联网计算机上，用于发现任务分发端、申请处理任务并可被停止或关闭。",
  "description_en": "A node server used in laboratory distributed computing or data-processing clusters. It typically runs on a networked computer to discover a task distributor, request work, and be stopped or shut down when needed.",
  "tag_hints": [
    "distributed computing",
    "cluster node",
    "task distribution",
    "network server",
    "lab data processing"
  ],
  "actions": [
    {
      "action_name": "distributor_url",
      "description": "获取分发器 URL",
      "description_en": "get distributor URL"
    },
    {
      "action_name": "num_tasks_to_request",
      "description": "获取待请求任务数量",
      "description_en": "get number of tasks to request"
    },
    {
      "action_name": "auto-stop",
      "description": "停止节点服务器",
      "description_en": "stop the node server"
    }
  ]
}

